import React, { useState } from "react";
import API_BASE_URL from "../config";

const CreateRentalListing = () => {
  const [form, setForm] = useState({ title: "", description: "", price: "", duration: "", image: "" });
  const sellerId = sessionStorage.getItem("userId");

  const handleSubmit = async (e) => {
    e.preventDefault();
    await fetch(`${API_BASE_URL}/api/rentals`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ...form, seller_id: sellerId }),
    });
    alert("Rental listing created!");
    setForm({ title: "", description: "", price: "", duration: "", image: "" });
  };

  return (
    <form onSubmit={handleSubmit}>
      <input placeholder="Title" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} />
      <textarea placeholder="Description" value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} />
      <input placeholder="Price" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} />
      <input placeholder="Duration" value={form.duration} onChange={(e) => setForm({ ...form, duration: e.target.value })} />
      <input placeholder="Image URL" value={form.image} onChange={(e) => setForm({ ...form, image: e.target.value })} />
      <button type="submit">Create Rental</button>
    </form>
  );
};

export default CreateRentalListing;
